# Combine all
all_data = v3 + new_examples

# Deduplicate
seen = set()
unique = []
for item in reversed(all_data):
    key = item["instruction"].lower().strip()
    if key not in seen:
        seen.add(key)
        unique.append(item)
unique.reverse()

with open("harz_training_data_v4.jsonl", "w") as f:
    for item in unique:
        f.write(json.dumps(item) + "\n")

print(f"v3 data: {len(v3)}")
print(f"New examples: {len(new_examples)}")
print(f"After dedup: {len(unique)}")
print("Saved to harz_training_data_v4.jsonl")
